#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(dirname -- "$(readlink -f -- "${BASH_SOURCE[0]}")")"
PYTHON="/work/smt4/azim.javed/envs/base_env/bin/python"
WORK="/work/smt4/azim.javed/sisyphus_work"

replay_job() {
    local job_id="$1"
    local config_id="$2"
    local output_dir="$WORK/i6_core/returnn/forward/ReturnnForwardJobV2.$job_id/output"
    local rasr_config="$WORK/i6_core/rasr/config/WriteRasrConfigJob.$config_id/output/rasr.config"

    (
        cd -- "$output_dir"
        # Keep generated bytecode disabled and matplotlib's cache beside the data.
        export PYTHONDONTWRITEBYTECODE=1
        export MPLCONFIGDIR="$output_dir/.matplotlib"
        "$PYTHON" "$SCRIPT_DIR/apply_output_quantizer.py" \
            --input "$output_dir/joint_activations_debug.npy" \
            --rasr-config "$rasr_config" \
            --output "$output_dir/joint_activations_post_quant.npy"
    )
}

# Digital QAT, then memristor ADC 4/4.
replay_job "9wPnV9PmMegQ" "UdOpdxX7iNj1"
replay_job "WzUWPLE5LRPZ" "yD7XDmiGBtpZ"
